// Simplified questionnaire: keep the basic company profile, then retain a
// small, representative set of easy-to-answer questions for each topic.
// Advanced multi-select and rating questions are omitted from the shorter flow.
const MAX_SIMPLE_QUESTIONS_PER_SECTION = 8;

const simplifySection = (section) => {
  if (section.id === 'company_profile') return section;

  const basicQuestions = section.questions.filter(
    (question) => question.type !== 'multiselect' && question.type !== 'rating'
  );

  if (basicQuestions.length <= MAX_SIMPLE_QUESTIONS_PER_SECTION) {
    return { ...section, questions: basicQuestions };
  }

  // Pick questions evenly so every topic remains represented.
  const step = (basicQuestions.length - 1) / (MAX_SIMPLE_QUESTIONS_PER_SECTION - 1);
  const questions = Array.from(
    { length: MAX_SIMPLE_QUESTIONS_PER_SECTION },
    (_, index) => basicQuestions[Math.round(index * step)]
  );

  return { ...section, questions };
};

export const questionnaireSections = allQuestionnaireSections.map(simplifySection);